}

static expr *scalar_mult(expr * vect, int64_t scalar, int affect_hints) /* <=== scalar_mult */ 
{
    expr *p = vect;

    while (p->type && p->type < EXPR_SEGBASE + SEG_ABS) {
        p->value = scalar * (p->value);
        if (hint && hint->type == EAH_MAKEBASE &&
            p->type == hint->base && affect_hints)
            hint->type = EAH_NOTBASE;
        p++;
    }
    p->type = 0;

    return vect;
}

static int end_expression_next(void) /* <=== end_expression_next */ 
{
    struct tokenval tv;
    char *p;
    int i;

    p = stdscan_get();
    i = stdscan(NULL, &tv);
    stdscan_set(p);

    return (i == ',' || i == ';' || i == ')' || !i);
}

static inline bool nasm_ctype(unsigned char x, enum nasm_ctype mask) /* <=== nasm_ctype */ 
{
    return (nasm_ctype_tab[x] & mask) != 0;
}

static expr *eval_floatize(enum floatize type) /* <=== eval_floatize */ 
{
    uint8_t result[16], *p;     /* Up to 128 bits */
    int sign = 1;
    int64_t val;
    size_t len;
    int i;
    const struct ieee_format *fmt;

    fmt = &fp_formats[type];

    scan();
    if (tt != '(') {
        nasm_nonfatal("expecting `('");
        return NULL;
    }
    scan();
    if (tt == '-' || tt == '+') {
        sign = (tt == '-') ? -1 : 1;
        scan();
    }
    if (tt != TOKEN_FLOAT) {
        nasm_nonfatal("expecting floating-point number");
        return NULL;
    }
    if (!float_const(tokval->t_charptr, sign, result, type))
        return NULL;
    scan();
    if (tt != ')') {
        nasm_nonfatal("expecting `)'");
        return NULL;
    }

    len = fmt->bytes - fmt->offset;
    if (len > 8)
        len = 8;                /* Max 64 bits */
    p = result + len;
    val = 0;
    for (i = len; i; i--) {
        p--;
        val = (val << 8) + *p;
    }

    begintemp();
    addtotemp(EXPR_SIMPLE, val);

    scan();
    return finishtemp();
}

static int scan(void) /* <=== scan */ 
{
    return tt = scanfunc(scpriv, tokval);
}

fatal_func nasm_verror_critical(errflags severity, const char *fmt, va_list args) /* <=== nasm_verror_critical */ 
{
    struct src_location where;
    errflags true_type = severity & ERR_MASK;
    static bool been_here = false;

    if (unlikely(been_here))
        abort();                /* Recursive error... just die */

    been_here = true;

    where = error_where(severity);
    if (!where.filename)
        where.filename = no_file_name;

    fputs(error_pfx_table[severity], error_file);
    fputs(where.filename, error_file);
    if (where.lineno) {
        fprintf(error_file, "%s%"PRId32"%s",
                errfmt->beforeline, where.lineno, errfmt->afterline);
    }
    fputs(errfmt->beforemsg, error_file);
    vfprintf(error_file, fmt, args);
    fputc('\n', error_file);

    die_hard(true_type, severity);
}

